import unittest

from shipcalc.calc import order_weight_kg, quote
from shipcalc.models import Item, Order


class CalcTest(unittest.TestCase):
    def setUp(self):
        self.order = Order([Item("MUG-01", "0.350", 2), Item("BOOK-07", "1.200")])

    def test_order_weight(self):
        self.assertEqual(order_weight_kg(self.order), "1.900")

    def test_empty_order(self):
        self.assertEqual(order_weight_kg(Order()), "0.000")

    def test_quote(self):
        result = quote(self.order, "eu")
        self.assertEqual(result, {"parcels": 1, "weight_kg": "1.900", "cents": 400 + 90 * 3})

    def test_quote_splits_heavy_orders(self):
        order = Order([Item("CRATE", "15.000", 2)])
        result = quote(order, "us")
        self.assertEqual(result["parcels"], 2)
        self.assertEqual(result["weight_kg"], "30.000")
        self.assertEqual(result["cents"], 2 * (900 + 150 * 29 + 500))


if __name__ == "__main__":
    unittest.main()
import unittest

from shipcalc.models import Item, Order
from shipcalc.units import WeightError


class ItemTest(unittest.TestCase):
    def test_weight_is_a_canonical_kilogram_string(self):
        self.assertEqual(Item("MUG-01", "0.250").weight_kg, "0.250")
        self.assertEqual(Item("MUG-01", "1.5").weight_kg, "1.500")

    def test_line_weight(self):
        self.assertEqual(Item("MUG-01", "0.350", 2).line_weight_kg(), "0.700")

    def test_round_trip(self):
        item = Item("BOOK-07", "1.200", 3)
        self.assertEqual(item.to_dict(), {"sku": "BOOK-07", "weight_kg": "1.200", "qty": 3})
        self.assertEqual(Item.from_dict(item.to_dict()).weight_kg, "1.200")

    def test_invalid_weight(self):
        with self.assertRaises(WeightError):
            Item("MUG-01", "heavy")
        with self.assertRaises(ValueError):
            Item("MUG-01", 250)

    def test_order_keeps_items(self):
        order = Order([Item("A", "1")])
        order.add(Item("B", "2"))
        self.assertEqual([i.sku for i in order.items], ["A", "B"])


if __name__ == "__main__":
    unittest.main()
import unittest

from shipcalc.rates import shipping_cents


class RatesTest(unittest.TestCase):
    def test_first_step(self):
        self.assertEqual(shipping_cents("0.500", "eu"), 400)

    def test_next_step(self):
        self.assertEqual(shipping_cents("0.501", "eu"), 490)

    def test_unknown_zone(self):
        with self.assertRaises(ValueError):
            shipping_cents("1.000", "mars")


if __name__ == "__main__":
    unittest.main()

