FILES = {}

FILES["shipcalc/units.py"] = '''"""Weight helpers. Weights are kilograms written as decimal strings with exactly
three decimal places (for example "0.250"). Arithmetic uses integers (grams)."""
import re

_INPUT = re.compile(r"[0-9]+(?:\\.[0-9]+)?")


class WeightError(ValueError):
    """An invalid weight, or a total over the carrier limit."""


def _invalid(value):
    return WeightError(f"invalid weight: {value!r}")


def kg_to_g(value):
    """Normalise value (kg) and return the exact whole number of grams."""
    if not isinstance(value, str) or not _INPUT.fullmatch(value):
        raise _invalid(value)
    whole, _, frac = value.partition(".")
    try:
        grams = int(whole) * 1000 + int(frac[:3].ljust(3, "0"))
        rest = frac[3:]
        if rest:
            rest_val = int(rest)
            half = 5 * 10 ** (len(rest) - 1)
            if rest_val > half or (rest_val == half and grams % 2 == 1):
                grams += 1
    except ValueError:  # absurdly long digit strings
        raise _invalid(value) from None
    return grams


def g_to_kg(grams):
    """Return the canonical kg string for a non-negative int number of grams."""
    if isinstance(grams, bool) or not isinstance(grams, int) or grams < 0:
        raise _invalid(grams)
    return f"{grams // 1000}.{grams % 1000:03d}"


def normalize_kg(value):
    """Return value in canonical form, rounding half to even, or raise WeightError."""
    return g_to_kg(kg_to_g(value))
'''

FILES["shipcalc/limits.py"] = '''from .units import WeightError, kg_to_g, normalize_kg

MAX_TOTAL_G = 2**31 - 1  # the carrier system stores grams in a signed 32-bit column


def check_total_kg(weight_kg):
    weight_kg = normalize_kg(weight_kg)
    if kg_to_g(weight_kg) > MAX_TOTAL_G:
        raise WeightError("total weight exceeds the carrier limit")
    return weight_kg
'''

FILES["shipcalc/calc.py"] = '''from .limits import check_total_kg
from .packing import split_parcels
from .rates import shipping_cents
from .units import g_to_kg, kg_to_g


def order_weight_kg(order):
    total = sum(kg_to_g(item.line_weight_kg()) for item in order.items)
    return check_total_kg(g_to_kg(total))


def quote(order, zone):
    parcels = split_parcels(order)
    cents = sum(shipping_cents(parcel.weight_kg, zone) for parcel in parcels)
    return {"parcels": len(parcels), "weight_kg": order_weight_kg(order), "cents": cents}
'''

FILES["shipcalc/cache.py"] = '''from .calc import order_weight_kg, quote

_STORE = {}


def quote_key(order, zone):
    return f"quote:v2:{zone}:{order_weight_kg(order)}:{len(order.items)}"


def cached_quote(order, zone):
    key = quote_key(order, zone)
    if key not in _STORE:
        _STORE[key] = quote(order, zone)
    return _STORE[key]


def clear():
