    return "\\n".join(rows)
'''

FILES["shipcalc/packing.py"] = '''from .units import g_to_kg, kg_to_g

MAX_PARCEL_G = 20000  # 20.000 kg


class Parcel:
    def __init__(self, weight_kg, skus):
        self.weight_kg = g_to_kg(kg_to_g(weight_kg))
        self.skus = list(skus)

    def add(self, weight_kg, sku):
        self.weight_kg = g_to_kg(kg_to_g(self.weight_kg) + kg_to_g(weight_kg))
        self.skus.append(sku)


def split_parcels(order):
    """First-fit decreasing. A unit heavier than the limit travels alone."""
    units = []
    for item in order.items:
        units.extend((kg_to_g(item.weight_kg), item.sku) for _ in range(item.qty))
    units.sort(key=lambda unit: (-unit[0], unit[1]))
    parcels = []
    for grams, sku in units:
        kg = g_to_kg(grams)
        for parcel in parcels:
            if kg_to_g(parcel.weight_kg) + grams <= MAX_PARCEL_G:
                parcel.add(kg, sku)
                break
        else:
            parcels.append(Parcel(kg, [sku]))
    return parcels
'''

FILES["shipcalc/rates.py"] = '''from .units import kg_to_g

ZONES = {"eu": (400, 90), "us": (900, 150), "world": (1500, 260)}  # (base cents, cents per extra step)
STEP_G = 500  # 0.500 kg
HEAVY_G = 10000  # 10.000 kg
HEAVY_SURCHARGE = 500


def shipping_cents(weight_kg, zone):
    try:
        base, per_step = ZONES[zone]
    except KeyError:
        raise ValueError(f"unknown zone: {zone!r}") from None
    grams = kg_to_g(weight_kg)
    steps = max(1, -(-grams // STEP_G))
    cents = base + per_step * (steps - 1)
    if grams > HEAVY_G:
        cents += HEAVY_SURCHARGE
    return cents
'''

